        assert_eq!(vars.get("KEY"), Some(&r"C:\Users\name".to_string()));
    }

    #[test]
    fn backslash_in_single_quoted_value_is_literal() {
        let content = r"KEY='C:\path\to\file'";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&r"C:\path\to\file".to_string()));
    }

    #[test]
    fn double_backslash_in_quoted_value() {
