        // The parser doesn't strip "export ", it becomes part of the key
        assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
        assert_eq!(vars.get("KEY"), None);
    }

    // --- Multiple equals signs ---

    #[test]
    fn multiple_equals_in_value() {
        let content = "KEY=a=b=c=d";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"a=b=c=d".to_string()));
    }

    #[test]
    fn base64_value_with_trailing_equals() {
        let content = "SECRET=dGVzdA==";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("SECRET"), Some(&"dGVzdA==".to_string()));
    }

    // --- Whitespace handling ---

    #[test]
    fn leading_whitespace_on_line_is_trimmed() {
        let content = "  KEY=value";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn trailing_whitespace_on_line_is_trimmed() {
        let content = "KEY=value   ";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    #[test]
    fn whitespace_only_value_after_trim() {
        // "KEY=   " => after line.trim() => "KEY=", value is ""
        let content = "KEY=   ";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"".to_string()));
    }

    #[test]
    fn tabs_around_equals() {
        let content = "KEY\t=\tvalue";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
    }

    // --- Special characters in values ---

    #[test]
    fn value_with_special_characters() {
        let content = "KEY=!@#$%^&*()";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"!@#$%^&*()".to_string()));
    }

    #[test]
    fn value_with_unicode() {
        let content = "GREETING=こんにちは";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("GREETING"), Some(&"こんにちは".to_string()));
    }

    #[test]
    fn quoted_value_with_newline_escape_sequence() {
        // Literal \n in content (not a real newline)
        let content = "KEY=\"line1\\nline2\"";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"line1\\nline2".to_string()));
    }

    // --- Duplicate keys ---

    #[test]
    fn duplicate_keys_last_value_wins() {
        let content = "KEY=first\nKEY=second";
        let vars = EnvFileParser::parse(content).unwrap();
        assert_eq!(vars.get("KEY"), Some(&"second".to_string()));
    }

    // --- Empty and whitespace-only content ---

    #[test]
    fn empty_content_returns_empty_map() {
        let vars = EnvFileParser::parse("").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn whitespace_only_content_returns_empty_map() {
        let vars = EnvFileParser::parse("   \n  \n   ").unwrap();
        assert!(vars.is_empty());
    }

    #[test]
    fn comments_only_returns_empty_map() {
        let content = "# comment 1\n# comment 2\n";
        let vars = EnvFileParser::parse(content).unwrap();
        assert!(vars.is_empty());
    }

    // --- load and load_optional with real files ---

    #[test]
    fn load_reads_file_from_disk() {
        let dir = std::env::temp_dir().join("env_file_test_load");
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join(".env");
        std::fs::write(&path, "FROM_FILE=yes\n").unwrap();

        let vars = EnvFileParser::load(&path).unwrap();
        assert_eq!(vars.get("FROM_FILE"), Some(&"yes".to_string()));

        std::fs::remove_file(&path).unwrap();
        std::fs::remove_dir(&dir).unwrap();
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let result = EnvFileParser::load(Path::new("/nonexistent/path/.env"));
        assert!(result.is_err());
    }

    #[test]
    fn load_optional_reads_existing_file() {
        let dir = std::env::temp_dir().join("env_file_test_optional");
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join(".env");
        std::fs::write(&path, "OPT=val\n").unwrap();

        let vars = EnvFileParser::load_optional(&path).unwrap();
        assert_eq!(vars.get("OPT"), Some(&"val".to_string()));

        std::fs::remove_file(&path).unwrap();
        std::fs::remove_dir(&dir).unwrap();
    }
}

